/* ===== VA Mastery course — in-depth modules mirroring a Certified Veteran Lending Specialist curriculum.
   Shape: {id,t,sections:[[heading, body(html-safe text, \n for paragraphs), cite]]}. VA Regional Loan Center: 877-827-3702. ===== */
const VA_RLC_PHONE="877-827-3702";
const VM=(id,t,sections)=>({id,t,sections});
const VA_COURSE=[
VM("why","Why this course & the misconceptions",[
["Education on the VA benefit is the answer","Fewer than 1 in 7 eligible veterans use the benefit, largely because agents, sellers and even loan officers repeat myths from the 1990s. The specialist's job is to be the person in the transaction who can cite the rule, show the data (VA loans have the lowest foreclosure rate of any program for most of the last 15 years, per MBA delinquency surveys) and move the file faster than a conventional file.","MBA NDS; VA Annual Benefits Report"],
["Veteran misconceptions","'I used it once so it's gone' (entitlement restores, and second-tier/bonus entitlement allows two VA loans at once). 'My credit is too bad' (VA has no minimum score; the lender sets overlays). 'It takes forever' (VA appraisals are assigned within 1–2 days and due in 7–10 business days in most of California). 'I need a DD-214 in hand' (lenders can pull the COE through WebLGY in seconds for most veterans). 'I can only buy once' and 'I can't buy a condo/multi-unit/manufactured home' are all false.","VA 26-7 Ch.2, 3, 7"],
["Seller misconceptions","'VA appraisals kill deals' (the Tidewater process gives the agent two business days to submit comps before a low value is issued). 'The seller has to pay all the veteran's costs' (false since the 2019 fee rule clarifications; the veteran can pay any reasonable and customary fee except the 1%-cap items and the unallowables; the seller is never required to pay anything). 'VA buyers are weak' (VA buyers pre-underwritten with residual income are the best qualified buyers in the market).","VA 26-7 Ch.8; Circular 26-22-11"],
["A great loan option for veterans","$0 down, no monthly MI, assumable, no prepayment penalty, lender-set credit, residual income instead of a DTI cap, up to 4% seller concessions plus unlimited closing costs, funding fee waived for disability-rated veterans, 100% cash-out, and the IRRRL for future rate drops.","38 U.S.C. §3710; 38 CFR 36.4300"]]),
VM("reach","Reaching VA & staying current",[
["VA Regional Loan Centers",`Lenders and veterans reach every Regional Loan Center through one number: ${VA_RLC_PHONE} (loan technicians, eligibility, appraisal and loan servicing). Hours 8 a.m.–6 p.m. ET. Use it for COE problems, entitlement restoration, appraisal timeliness complaints, SAR/LAPP questions, and borrower delinquency help. The Phoenix RLC covers California, Nevada and Arizona for appraisal/construction; eligibility is centralized (Atlanta Eligibility Center via WebLGY). Veterans' crisis: 988 then press 1.`,"benefits.va.gov/homeloans/contact_rlc_info.asp"],
["Getting VA updates","Subscribe to VA Lender circulars (benefits.va.gov/homeloans/resources_circulars.asp) and the VA Lenders Handbook (M26-7) change log; join the VALERI servicer notices if you service; read the FHFA conforming limit release each November (sets the VA county limits for partial-entitlement borrowers); watch the funding-fee statutory tables (currently set through 2031 by the Blue Water Navy Act as amended).","VA Circulars; M26-7"]]),
VM("what","What a VA guaranteed loan is",[
["Important features","The VA guarantees a portion of the loan (25% of the loan amount up to the applicable guaranty) to the lender so the lender can make a 100% LTV loan without MI. The lender underwrites and funds; VA sets eligibility, property, fee and underwriting rules. Fixed or hybrid ARM terms to 30 years; purchase, construction, cash-out, IRRRL, energy improvements and alteration/repair are eligible purposes.","38 CFR 36.4300 et seq."],
["What 'guaranteed' means","If the veteran defaults, VA pays the lender the lesser of the loss or the guaranty amount. The guaranty is 25% of the loan for borrowers with full entitlement (no cap since the 2020 Blue Water Navy Act removed loan limits for full-entitlement veterans); for partial entitlement the guaranty is the remaining entitlement and the lender requires 25% coverage through a down payment.","38 U.S.C. §3703"],
["Lender overlays","Anything stricter than the Handbook is an overlay: credit score floors (580–640), max DTI (often 55–60% with residual at 120%), manual-underwrite limits, manufactured-home exclusions, 2–4 unit experience rules. Shop overlays, not rates, for tough files; brokers can place a file with the lender whose overlay matches the file.","Lender matrices; M26-7 Ch.4"]]),
VM("purpose","What a VA loan can be used for",[
["Requirements for approval","Eligible veteran (COE), eligible purpose, owner-occupancy, satisfactory credit, stable income with residual income meeting the table, acceptable property (NOV with MPRs met), allowable fees, and a properly executed loan package (26-1802a, 26-0286 commitment, 26-1820 report).","M26-7 Ch.3–4"],
["Eligible purposes","Buy or build a 1–4 unit home (or condo in a VA-approved project) the veteran will occupy; buy a manufactured home and/or lot; buy a residential property plus a farm the veteran operates; repair/alter/improve the home (including energy efficiency up to $6,000 without separate underwriting); refinance (IRRRL or cash-out); simultaneous purchase and improvement.","38 CFR 36.4301; M26-7 Ch.3"],
["Ineligible purposes","Investment properties the veteran will not occupy, second homes, bare land without a home to be built, commercial property, co-ops (unless the project is approved, extremely rare), timeshares, property outside the U.S. and territories, and loans where the veteran is not on title.","M26-7 Ch.3"]]),
VM("elig","Eligibility & the COE",[
["Active duty: 90-day and 181-day rules","Wartime service (e.g., Gulf War era: 8/2/1990–present): 90 continuous days of active duty. Peacetime periods: 181 continuous days. Currently serving members qualify after 90 continuous days; a statement of service from the commander (name, SSN, DOB, entry date, lost time, unit) substitutes for a DD-214. Discharge must be other than dishonorable; OTH requires VA character-of-discharge review.","38 U.S.C. §3702; M26-7 Ch.2"],
["Two-year rule if no longer on active duty","Veterans who enlisted after 9/7/1980 (officers after 10/16/1981) must have completed 24 continuous months of active duty or the full period called/ordered (at least 90 days wartime/181 peacetime), unless discharged early for hardship, convenience of the government (after 20 months), RIF, a service-connected disability, or certain medical conditions.","38 U.S.C. §5303A"],
["Reservists & the points summary","Six years in the Selected Reserve or National Guard with an honorable discharge, retirement, or continued service, OR 90 days of Title 10 active duty (activated), OR since 2021 (Guard) 90 days of Title 32 full-time duty with at least 30 consecutive. Proof: NGB-22/NGB-23 (Guard), points statement/retirement points summary (Reserve: a 'good year' is 50+ points; six qualifying years are needed), DD-214 for activations. Reservists pay a slightly different funding fee only on loans closed before 1/1/2020 — the fee is now identical.","38 U.S.C. §3701(b)(5); PL 116-315"],
["National Guard","Same six-year rule, plus Title 10 activation (90 days) or Title 32 full-time (90 days, 30 consecutive) since the 2021 Johnny Isakson Act. Guard members must separate honorably or still be serving. State active duty alone does not count.","PL 116-315 §2003"],
["Surviving spouses","Un-remarried spouse of a veteran who died in service or from a service-connected disability; spouse of a service member MIA/POW for 90+ days; spouse who remarried after age 57 and after 12/16/2003; spouse of a veteran who was totally disabled (not necessarily cause of death) under certain rules. Surviving spouses with DIC are funding-fee exempt. Apply with VA Form 26-1817 and the veteran's DD-214 and death certificate; the COE is issued by the Eligibility Center, not WebLGY instantly.","38 U.S.C. §3701(b)(2); M26-7 Ch.2.7"],
["Other qualifying service","Public Health Service and NOAA commissioned officers, Service Academy cadets/midshipmen, certain WWII Merchant Mariners and Philippine Scouts, and some allied-forces veterans. Military spouses are not eligible on their own but can co-borrow.","M26-7 Ch.2"],
["Determining eligibility & the COE","The Certificate of Eligibility (VA Form 26-8320) states entitlement, prior loans, funding-fee exemption status and conditions. Lenders request it through WebLGY (instant for ~70% of veterans); veterans through eBenefits/VA.gov or by mailing VA Form 26-1880 to the Eligibility Center. Read: 'Basic entitlement $36,000' (means full entitlement with no active loans), 'Entitlement charged' amounts, 'Prior loan: paid in full / not restored', and the 'Conditions' section (e.g., 'SOE' substitution of entitlement, 'must occupy', funding-fee exempt).","M26-7 Ch.2"],
["Acceptable evidence of service","DD-214 (Member 4 or Service 2 copy showing character of service and narrative reason), statement of service (active), NGB-22, points statement, retirement orders, or a VA letter. Missing documents: request through the National Personnel Records Center (milConnect/eVetRecs, SF-180) or through the veteran's county Veterans Service Officer; VA can often verify service internally when the lender's WebLGY request fails ('refer to eligibility center').","M26-7 Ch.2.4"],
["Previously used eligibility: restoration types","Basic restoration (loan paid in full and the property sold): submit 26-1880 with the HUD-1/CD showing payoff and sale; WebLGY often restores automatically. One-time restoration: loan paid in full but the veteran still owns the home (e.g., refinanced to conventional or paid off) — allowed once in a lifetime, after which all entitlement used on that property is permanently charged until the property is sold. Rapid restoration (not a VA term): the lender uploads the payoff/closing statements and calls the RLC to restore same-day when the veteran's new purchase closes before the sale records. Substitution of entitlement: a VA-eligible buyer assumes the loan and substitutes their entitlement so the seller's is restored. Compromise claim / foreclosure: entitlement stays charged until VA is repaid the loss (or a compromise is accepted).","M26-7 Ch.2.6"],
["What the COE tells the lender","Full entitlement = no county limit, $0 down for any amount the veteran qualifies for. Partial entitlement = remaining entitlement shown; max $0-down loan = (county limit × 25% − entitlement used) × 4; above that the veteran pays 25% of the difference as down payment. Funding-fee exempt flag; 'bonus/second-tier' math (county limit × 25% − used) applies when buying while keeping an existing VA loan (second home purchase via PCS).","M26-7 Ch.3.3–3.4"]]),
VM("maxloan","Maximum loan amounts, down payments & occupancy",[
["Calculating purchase down payments","Full entitlement: $0 down at any price if the loan amount ≤ appraised value (NOV) and the veteran qualifies. Partial entitlement: required down = 25% × (price − (county limit − 4 × entitlement used))... practical formula: available guaranty = 25% of the county limit − entitlement used; max $0-down loan = available guaranty × 4; down payment = 25% of (price − max $0-down loan). The Entitlement tab computes this and also the funding fee impact (down ≥5% drops the fee to 1.50%, ≥10% to 1.25%).","M26-7 Ch.3.4"],
["Maximum loan amounts for refinances","IRRRL: existing VA loan balance + allowable costs + up to 2 discount points + funding fee (0.5%), plus energy improvements; no appraisal value test unless the lender requires. Cash-out: 100% of appraised value (reasonable value from the NOV) including the funding fee (some lenders overlay to 90%); Type I (no cash-out, VA-to-VA) and Type II (any cash or non-VA-to-VA) both must pass the net-tangible-benefit test and seasoning (210 days + 6 payments).","38 CFR 36.4306; Circular 26-19-22"],
["Occupancy: how long and how quickly","The veteran (or spouse, or dependent child with a POA/legal guardian) must certify intent to occupy as a primary residence within a reasonable time — 60 days after closing is standard; up to 12 months with documented circumstances (e.g., deployment, retirement within 12 months, home under renovation). There is no minimum period of occupancy after that in the statute; lenders expect 12 months by convention and the occupancy certification is sworn on VA Form 26-1802a. Intermittent occupancy (shift workers, OTR truckers) is acceptable if the home is the primary residence of record.","38 U.S.C. §3704(c); M26-7 Ch.3.5"],
["Spouse certifying occupancy","A spouse may certify occupancy for a deployed or stationed-away service member; a dependent child may occupy with a legal guardian/attorney-in-fact when the veteran is deployed. Single service members deploying must document their intent to return. A non-spouse co-borrower cannot satisfy occupancy.","M26-7 Ch.3.5"]]),
VM("credit","Credit & liabilities",[
["How VA analyzes credit","VA has no minimum score; the lender reviews the pattern of credit over the past 12 months with emphasis on housing payment history. 'Satisfactory credit': no more than one 30-day late on any account in the past 12 months is the common lender interpretation; accounts in good standing after re-establishment; isolated lapses explained by LOE. Scores drive pricing and overlays, not VA eligibility.","M26-7 Ch.4.7"],
["No credit score or history","VA permits non-traditional credit: 12 months of verified rent plus utilities, insurance, phone, childcare, or other recurring obligations (at least three sources). Manual underwrite only; residual income must exceed the table by 20% is a common overlay.","M26-7 Ch.4.7"],
["Bankruptcy","Chapter 7: 2 years after discharge; 12–24 months with documented extenuating circumstances (medical, job loss) and re-established credit. Chapter 13: 12 months of satisfactory plan payments with trustee approval, or discharge with good post-discharge credit. VA's standard is 'satisfactory credit has been re-established'.","M26-7 Ch.4.7"],
["Foreclosure, DIL, short sale, prior VA loss","2 years after foreclosure or deed-in-lieu (12 months with extenuating circumstances). Short sale: treated like a foreclosure if a loss was sustained. If the prior loss was on a VA loan, entitlement remains charged until VA is repaid (the veteran may still buy with remaining entitlement and a down payment).","M26-7 Ch.4.7; Ch.2.6"],
["Judgments, federal debts, tax liens, CAIVRS","Judgments must be paid or under a 12-month-performing repayment plan. Delinquent federal debt (student loans, SBA, prior VA/FHA claim) shows on CAIVRS and must be resolved, in a repayment plan, or a claim must be paid; the lender pulls CAIVRS on every borrower. Tax liens: paid, subordinated, or in an IRS installment agreement with payments counted in debts.","M26-7 Ch.4.7"],
["Collections, consumer credit counseling, community property","Collections need not be paid (lender overlays vary; medical ignored) but their pattern matters; unpaid collections are counted in debt only if a payment is required. Consumer credit counseling with 12 months of on-time payments is neutral. Community property states (CA, NV, AZ, TX, WA, ID, LA, NM, WI): the non-purchasing spouse's debts are counted (VA requires it for the residual/DTI analysis) and their credit is pulled, though their credit history itself is not a reason for denial.","M26-7 Ch.4.7–4.8"],
["Marriage, divorce, non-purchasing spouses","Divorce decrees assign debts; the lender uses the decree plus 12 months of the ex-spouse's payment evidence to exclude a debt. Child/spousal support paid is a liability; received is income with 3 years continuance. A non-purchasing spouse's income cannot be used but their debts are (community property states). Spousal signatures may be required on security instruments.","M26-7 Ch.4"],
["Child care and job-related expenses","VA counts childcare as a monthly liability for residual income (not DTI) when a child under 12 lives in the home and both parents work; job-related expenses (union dues, commuting beyond the ordinary, uniforms) also reduce residual. If no childcare cost, the lender obtains a signed statement of who provides care.","M26-7 Ch.4.9"]]),
VM("income","Income & residual income",[
["Calculating residual income","Residual = gross income − federal/state income taxes − Social Security/Medicare − monthly shelter expense (PITI + HOA) − maintenance/utilities (14¢ × sq ft) − other liabilities (all debts, childcare, support, job expenses). Compare to the table by region (West: $1,117 for a family of 4 on loans >$80k) and family size; 'as a general guide' the underwriter can approve with residual slightly below the table when strong compensating factors exist, but DTI >41% requires residual ≥120% of the table (or a justification statement).","M26-7 Ch.4.9; Residual income tables"],
["Income taxes and deductions","Use the actual withholding on the LES/pay stub or IRS/state tables for the filing status; VA requires state income tax even in no-tax states to show $0. Non-taxable income (BAH, BAS, disability) is not grossed up for residual (only for DTI, at 125% by most lenders); residual counts the full amount with no tax deduction.","M26-7 Ch.4.9"],
["Family size and compensating factors","Family size counts everyone the veteran supports (spouse, children, dependent parents); a non-purchasing spouse is counted. Compensating factors: residual above 120%, long-term employment, minimal payment shock, significant liquid assets, high credit score, conservative use of credit, military benefits (BAH continuing), tax-free income, DTI driven by housing.","M26-7 Ch.4.10"],
["Time on job & stability","Two years of continuous employment is preferred; less is acceptable with offsetting factors (training, prior military occupation matching the civilian job, strong residual). Active-duty applicants: the LES plus a statement of service; if ETS/retirement is within 12 months, document re-enlistment, a civilian job offer, or retirement income to show continuance.","M26-7 Ch.4.2"],
["Active military pay (LES)","Read the LES: base pay, BAH (verify the rate for the duty station and dependents; BAH may be used as qualifying income when the home is in the commuting area), BAS, special pays (hazard, flight, sea, SDAP, language, clothing) with continuance; count the 'ETS' date and 'YOS'. Deployed members: use POA (specific or general with VA-specific language) and the Alive and Well certification.","M26-7 Ch.4.2; DFAS LES guide"],
["Reservists, Guard & recently activated","Drill pay counts if 2 years history (or reasonably expected to continue); recently activated Guard/Reserve use the active-duty pay with orders showing 12+ months remaining; civilian job hold rights under USERRA support continuance.","M26-7 Ch.4.2"],
["Disability, child support, overtime, bonus, second job","VA disability compensation: use the award letter, non-taxable, no continuance letter needed. Child support: 3 years continuance and 12 months receipt. OT/bonus/second job: 2-year average, with 12 months acceptable when clearly ongoing.","M26-7 Ch.4.2"],
["Self-employment and commission","2 years of returns (1 year with a prior occupation match); losses reduce income; depreciation added back; commission 2-year average with 2106 expenses deducted when applicable (post-TCJA, mostly irrelevant).","M26-7 Ch.4.2"],
["Rental income","Existing rentals: Schedule E or leases with 25% vacancy factor if no history; departure residence: lease + 3 months PITI reserves (lender overlay) + equity rules. Multi-unit purchase: 75% of market rents can be counted only with prior landlord experience (or using a property manager, lender-dependent) and 6 months PITI reserves.","M26-7 Ch.4.2"],
["Assets, reserves, gift funds, arm's length","VA requires no reserves on 1-unit purchases (lenders may on 2–4 units: 6 months). Gift funds from relatives with a gift letter and transfer evidence; the veteran can use gifts for closing costs. Identity-of-interest/non-arm's-length sales (family) are allowed with standard documentation; equity gifts are acceptable.","M26-7 Ch.4.4"]]),
VM("joint","Joint loans",[
["VA and joint loans","Veteran + spouse: standard. Veteran + non-veteran, non-spouse: VA guarantees only the veteran's portion (25% of their share), so the lender requires a down payment on the non-veteran's half — a 'joint loan' requiring VA prior approval. Two veterans each using entitlement: full guaranty on both halves. Lenders rarely offer non-spouse joint loans; price them as 12.5% down conventional-equivalents.","M26-7 Ch.7.2"],
["GNMA pooling limits","Ginnie Mae will not pool a VA loan where the guaranty is less than 25% without the lender's down-payment fix; this is why partial-entitlement loans require 25% coverage.","Ginnie Mae MBS Guide Ch.24"],
["Occupancy, units, credit, residual on joint loans","All borrowers' income and debts are combined; residual income uses the combined family; each borrower must meet credit; the veteran must occupy. 2–4 units allowed with one veteran occupying.","M26-7 Ch.7"],
["Prior approval & funding fee on joint loans","Non-spouse joint loans go to VA for prior approval (26-1802a with the joint-loan addendum). The funding fee applies only to the veteran's portion of the loan amount.","M26-7 Ch.7.2"]]),
VM("compare","How VA compares to other programs",[
["Zero down, no PMI, assumable, lower rates","VA 30-year rates have averaged 0.25–0.50% below conventional for most of the past decade (Optimal Blue/ICE data). No MI saves $150–$400/month vs FHA/conventional at 96.5–97% LTV. Assumability lets the next buyer take over a 3% loan (with substitution of entitlement).","ICE Mortgage Monitor; 38 CFR 36.4303"],
["Funding fee tables","Purchase/construction: first use 2.15% (<5% down), 1.50% (5–9.99%), 1.25% (10%+); subsequent use 3.30% / 1.50% / 1.25%. Cash-out: 2.15% first / 3.30% subsequent. IRRRL 0.50%. Manufactured (chattel) 1.00%. Assumptions 0.50%. Exempt: receiving or entitled to compensation (10%+), Purple Heart recipients on active duty, surviving spouses receiving DIC, pending claim later approved (refund).","38 U.S.C. §3729"],
["VA vs FHA","FHA: 3.5% down, 1.75% UFMIP + annual MIP for life, 6% seller limit, property/flip rules; VA: $0 down, one-time fee (waivable), no MI, 4% concessions + unlimited costs, no flip rule. Choose FHA only when the veteran lacks entitlement or a non-occupant co-borrower is needed.","HUD 4000.1; M26-7"],
["VA vs conventional and jumbo","Conventional needs 3–5% down with MI below 80% LTV and LLPAs by score; VA has no LLPA grid (lender pricing only) and no county limit with full entitlement: a $1.5M 'VA jumbo' at $0 down beats a conventional jumbo requiring 10–20% down, 720+ and 12 months reserves.","Fannie LLPA; M26-7 Ch.3"],
["FHFA county limits","Only matter for partial entitlement. 2026: $832,750 baseline, San Diego $1,104,000, LA/Orange $1,249,125 (verify FHFA table).","FHFA"],
["Energy efficient loans","Up to $6,000 in energy improvements added to the loan with a contractor estimate (no additional underwriting ≤$3,000; $3,001–$6,000 requires the payment increase ≤ utility savings); above $6,000 requires full underwriting of the increase.","M26-7 Ch.7.3"],
["Other benefits: SCRA, SAH/SHA, property tax, POA, Alive and Well","SCRA caps pre-service debt interest at 6% and protects against foreclosure during service + 1 year. SAH grant up to ~$121,812 (FY2026) for severe disabilities; SHA up to ~$24,405; TRA for adapting a family member's home. Property tax exemptions for disabled veterans in CA, NV, AZ, TX, FL, IL. POA closings require the veteran's 'Alive and Well' statement (verified within 1 day of closing) and a POA with VA-specific language (intent to occupy, loan amount, property); general military POAs usually suffice when the specific loan is referenced.","50 U.S.C. §3901; 38 CFR 36.4337; M26-7 Ch.9"]]),
VM("fees","Closing costs & fees",[
["Allowable itemized fees","Appraisal (VA fee schedule), credit report, recording, title exam and insurance, survey, flood determination, prepaids (taxes, hazard insurance, interest), VA funding fee, discount points (reasonable), MERS fee, and the 1% flat origination charge OR itemized lender fees (never both).","38 CFR 36.4313; Circular 26-22-11"],
["The 1% origination fee and 'fees limited to 1%'","A lender may charge a flat 1% (which covers processing, underwriting, doc prep, application, etc.) or itemize up to 1% of allowed unallowables; anything the veteran cannot pay (brokerage fees, attorney fees for the lender, notary, escrow/settlement fee above 1%, document prep, pest inspection on purchases in most states — now allowed in all states since 2022 Circular 26-22-11, tax service, loan closing fees) must be paid by the seller, lender, or through a lender credit.","38 CFR 36.4313(d)"],
["Reasonable discount points","Points must be reasonable and typically ≤2 on IRRRLs financed; on purchases points are allowable and can be seller-paid; VA may question points above market.","M26-7 Ch.8"],
["Attorney, brokerage fees, prepayment penalties","The veteran may pay their own attorney for personal representation; may not pay the lender's attorney or any brokerage fee (broker compensation must be lender-paid or within the 1%). VA loans never carry prepayment penalties.","38 CFR 36.4313; 36.4310"],
["Who pays excess fees? Seller concessions vs seller credit","Seller credit toward closing costs and prepaids is unlimited (within the actual costs). Seller concessions (prepaid taxes/insurance beyond standard, funding fee, debt payoff, gifts, appliances, escrow for repairs) are capped at 4% of the reasonable value. The lender/broker may pay unallowables through a lender credit. The funding fee can be seller-paid as a concession.","M26-7 Ch.8.5"]]),
VM("appraisal","Appraisals, Tidewater, ROV & the NOV",[
["Home inspections vs VA appraisals","The appraisal is for value and MPRs; it is not an inspection. Veterans are encouraged (not required) to get a home inspection; VA's 'Notice of Value' includes a statement that the appraisal is not a guarantee of condition.","M26-7 Ch.10"],
["Ordering and timeliness; transfers","The lender (LAPP/SAR) orders the appraisal through WebLGY (VA Form 26-1805 equivalent) as soon as the contract is signed; the VA-assigned fee appraiser must complete within the RLC timeliness standard (most CA counties 7–10 business days). A VA appraisal belongs to the veteran's case number and transfers to a new lender via WebLGY with the old lender's release — the veteran does not pay twice.","M26-7 Ch.10"],
["Unprofessional appraiser feedback; how value is determined","Report timeliness/conduct through the RLC Construction & Valuation unit (877-827-3702) — not the appraiser. Appraisers use the sales comparison approach with VA's Minimum Property Requirements overlay; they may use pending sales and must address agent-supplied comps during Tidewater.","M26-7 Ch.10"],
["Tidewater & low appraisals","When the appraiser expects value below the contract price, they must notify the point of contact (usually the lender/SAR) before completing: the Tidewater Initiative gives 2 business days to submit additional comps, cost/upgrade info, or a concession explanation. If value still comes in low, the SAR issues the NOV at the lower value.","Circular 26-03-11; M26-7 Ch.10.9"],
["Disputing value: SAR review, then ROV","First channel: the lender's Staff Appraisal Reviewer may adjust value up to 5% with supporting data (LAPP). Second channel: the veteran/lender submits a Reconsideration of Value through the RLC with up to 3 new comps, errors identified, and a signed request; VA responds in ~5 business days. A second appraisal is not allowed to 'shop' value; only when the first is deficient.","M26-7 Ch.10.10"],
["Buyer's options if value is low","Pay the difference in cash (gift funds allowed), cancel under the VA escape clause (the Amendatory Clause lets the veteran walk and keep the deposit), or renegotiate price/credits. Seller concessions cannot exceed 4% of the NOV value.","38 CFR 36.4303(k); M26-7 Ch.9"],
["The Notice of Value","Issued by the SAR within 5 business days of the appraisal upload; lists the reasonable value, MPR repair conditions, pest inspection requirement, condo approval, flood, well/septic, private road, and 'subject to' conditions; valid 6 months (existing) or 12 months (proposed construction).","M26-7 Ch.13"],
["Costs, travel fees, late charges, cancelling, complex cases","VA sets maximum appraisal fees by state (CA: ~$700–$1,000 single family; mileage beyond the fee area adds travel); the veteran may pay the invoice. Cancellation after inspection incurs a fee; unusual properties (acreage, luxury, mixed-use) justify complex-assignment fee requests approved by the RLC.","VA appraisal fee schedule"]]),
VM("mpr","Property condition & MPRs",[
["MPRs: safe, sound, sanitary","Safe: no exposed wiring, missing handrails on 3+ steps, broken glass, trip hazards, lead-based paint (chipping/peeling pre-1978 must be scraped and repainted), crawlspace access. Sound: roof with remaining life (3+ years typical), no structural defects, no active water intrusion, adequate attic ventilation, foundations without active movement. Sanitary: potable water (well test when not public), sewage disposal (septic inspection when evidence of failure), functional heating (permanent source), hot water, no infestation.","M26-7 Ch.12"],
["Outside the appraiser's expertise; permitted vs non-permitted additions","The appraiser can condition on expert inspections (roof, foundation, HVAC, septic, well, structural engineer). Non-permitted additions: the appraiser may include them if built in a workmanlike manner and typical for the market, exclude them from value, or require permits — the lender/SAR decides based on local practice; unpermitted bedrooms/garage conversions commonly get zero value.","M26-7 Ch.12"],
["Mixed use","Residential must predominate; commercial use ≤25% of floor area, zoning must permit residential, and the property must be primarily residential in character.","M26-7 Ch.12"],
["Pest (termite) inspections","Required in the VA probability map's 'very heavy/moderate to heavy' areas (all of California, Nevada's Clark County, Arizona, Florida, Texas, Illinois southern half). Section 1 items (active infestation, damage) must be cleared before closing; Section 2 (conditions conducive) are recommended. Who pays: since Circular 26-22-11 the veteran may pay the inspection fee in any state; repairs are negotiable (seller typically). Re-inspections (VA Form 26-1839 compliance inspection) verify repairs before funding.","M26-7 Ch.12.6; Circular 26-22-11"],
["Eligible properties; flips; SFR/PUD; condos","VA has no title seasoning/flip rule (lenders may overlay; FHA's 90-day rule does not apply). SFR and PUDs are routine; condos must be in a VA-approved project (search lgy.va.gov Condo Report); unapproved projects need the HOA docs submitted for approval (30–60 days; free), or buy in an FHA-approved project? — no, FHA approval does not transfer. Manufactured homes must be on permanent foundations and titled as real property.","M26-7 Ch.12; 38 CFR 36.4362"],
["Using the VA search engine","lgy.va.gov/lgyhub/condo-report: search by name/city/ID; status 'Accepted without conditions' is good; 'HUD accepted' legacy approvals still count; 'Unaccepted' or 'rejected' requires a new submission package (CC&Rs, bylaws, budget, reserves, litigation, owner-occupancy).","lgy.va.gov"]]),
VM("refi","Refinances & alteration/repair loans",[
["IRRRL: seasoning, fees, NTB","Refinances an existing VA loan to a lower rate (0.5% minimum reduction fixed-to-fixed; 2% ARM-to-fixed unless energy improvements) with no appraisal or income verification required by VA (lenders may require a credit review). Seasoning: 210 days after the first payment due date AND 6 monthly payments. Fees: all allowable costs + funding fee 0.5% + up to 2 points may be financed; recoupment of fees must be ≤36 months (statutory, excludes prepaids/escrows/funding fee is included? — the 2024 rule counts all fees except prepaids and the funding fee... verify current VA circular). Net tangible benefit: lower rate, lower P&I, ARM-to-fixed, shorter term, or energy improvements; and the lender must disclose the 36-month recoupment on the IRRRL comparison statement.","38 CFR 36.4307; Circular 26-18-13; PL 115-174"],
["Cash-out Type I and Type II","Type I: the new loan amount ≤ payoff of the existing VA loan + costs (no cash in hand) — VA-to-VA 'rate/term'. Type II: any cash out or non-VA-to-VA. Both: full appraisal (NOV), 100% LTV max including the funding fee (2.15%/3.30%), credit/income qualifying, 210-day/6-payment seasoning on the loan being refinanced, occupancy certification, and the NTB test with 8 enumerated benefits (at least one), plus the home-equity disclosure comparing the old loan, new loan and the equity removed.","38 CFR 36.4306; Circular 26-19-22"],
["Free-and-clear properties","A veteran with no mortgage can take a VA cash-out (Type II) up to 100% of value to pull equity — a powerful tool for debt consolidation; NTB test still applies (lower payment vs. consolidated debt).","38 CFR 36.4306"],
["Alteration & repair loans","Purchase or refinance plus repairs completed after closing (VA 'A&R' / renovation): licensed contractor, VA appraisal as-completed, escrow of funds, compliance inspection; lender programs cap repairs (often $50,000–$100,000). Underwriting is standard VA with the as-completed value; the energy-improvement route ($6,000) is simpler for small upgrades.","M26-7 Ch.7.4; Circular 26-18-6"]]),
];
/* Tools for the course: reservist points, surviving spouse, restoration, POA/alive and well, flip/termite quick rules */
const VA_SPOUSE_TEST=(a)=>{const ok=[],no=[];if(a.cause==="service")ok.push("Veteran died in service or from a service-connected disability → eligible");else if(a.cause==="totally_disabled")ok.push("Veteran was rated totally disabled (eligible under 38 U.S.C. §3701(b)(2)(B) rules: total disability for 10+ years immediately preceding death, or 5 years from discharge, or POW 1 year) → eligible if the rating conditions are met");else if(a.cause==="mia")ok.push("Service member MIA/POW 90+ days → eligible (one-time use)");else no.push("Death not service-connected and no total-disability rating → not eligible");
 if(a.remarried==="n")ok.push("Not remarried → eligible");else if(a.remarried==="after57")ok.push("Remarried after age 57 and after 12/16/2003 → eligibility retained");else no.push("Remarried before 57 → not eligible (unless the later marriage ended)");
 const elig=no.length===0;return {elig,ok,no,next:elig?"File VA Form 26-1817 (Request for Determination of Loan Guaranty Eligibility — Unmarried Surviving Spouses) with the veteran's DD-214 and death certificate (and DIC award letter for funding-fee exemption). Issued by the Eligibility Center, not instantly through WebLGY; allow 2–4 weeks. Questions: "+VA_RLC_PHONE:"Consider: the spouse's own service, a joint loan with an eligible co-borrower, or FHA/conventional alternatives. Confirm with the Eligibility Center at "+VA_RLC_PHONE};};
const VA_RESTORE_TEST=(a)=>{const r=[];if(a.paid==="y"&&a.sold==="y")r.push(["Basic restoration","Loan paid in full and property disposed of. Submit 26-1880 with the final CD/HUD-1 showing payoff and sale; WebLGY usually restores automatically. Unlimited uses."]);
 if(a.paid==="y"&&a.sold==="n")r.push(["One-time restoration","Loan paid in full (refinanced to non-VA or paid off) but veteran still owns the home. Allowed ONCE in a lifetime; after that, entitlement used on that property is charged until the property is sold. Decide whether to save the one-time use."]);
 if(a.paid==="n"&&a.sold==="n"&&a.assumed==="n")r.push(["Second-tier (bonus) entitlement","Keep the existing VA loan (e.g., PCS, convert to rental). Available guaranty = 25% × county limit of the new property − entitlement charged; max $0-down = that × 4; otherwise 25% down on the difference. Run the Entitlement tab."]);
 if(a.assumed==="y")r.push(["Substitution of entitlement","The assuming buyer is VA-eligible and substituted entitlement (VA Form 26-8106 with the servicer's approval). The seller's entitlement is restored once VA records the SOE; if a non-veteran assumed, the entitlement stays charged until that loan is paid."]);
 if(a.loss==="y")r.push(["Compromise claim / foreclosure","VA paid a claim. Entitlement is charged by the claim amount until repaid (or a compromise offer is accepted by the RLC debt management center 800-827-0648). Remaining entitlement may still support a loan with a down payment; 2-year waiting period after foreclosure applies."]);
 if(a.timing==="same_day")r.push(["Same-day ('rapid') restoration","Selling and buying concurrently: have the lender upload the payoff statement and signed closing statement of the sale to WebLGY and call "+VA_RLC_PHONE+" to request same-day restoration; or close the sale first (even hours earlier) and fund the purchase after recording."]);
 return r.length?r:[["No restoration needed","If the veteran never used entitlement or it already shows as fully available on the COE, proceed."]]};
const VA_RESERVE_POINTS=(years)=>years.map((p,i)=>({yr:i+1,pts:+p||0,good:(+p||0)>=50}));
/* Tricks of the trade for VA approval (shown at the top of the Tough-file strategies tab) */
const VA_TRICKS=[
["DTI over 41%? 120% residual income overcomes it","VA's 41% DTI is a benchmark, not a cap. If DTI exceeds 41%, the loan is still approvable when residual income is at least 120% of the regional table (M26-7 Ch.4.10: 'ratio exceeded by 20% or more'). DU and LPA know this: a VA file over 41% DTI with residual below 120% of the table will almost always come back REFER, and one at 120%+ will usually APPROVE. Residual income (the veteran's budget after shelter, taxes, debts, childcare and maintenance) trumps DTI — and lenders' DTI overlays are their own, not VA's.","M26-7 Ch.4.9–4.10 · NAMB CVLS"],
["First thing to check on any REFER: residual listed vs. required","Open the findings and compare the residual income the AUS calculated against the table requirement for the region and family size. Wrong family size, missing non-taxable income, taxes estimated too high, HOA keyed as a debt, childcare entered twice, or square footage inflating maintenance (14¢ × sq ft) are the usual culprits. Fix the inputs and re-run before you ask for a manual underwrite.","M26-7 Ch.4.9"],
["Run the residual worksheet before you quote a payment","Most LOs check residual last. Check it first: it tells you the max PITI the veteran can carry at 120% of the table, which sets the price range and the concession strategy (seller-paid buydown or debt payoff raises residual).","M26-7 Ch.4.9"],
["Non-taxable income counts at 100% for residual","BAH, BAS, VA disability and other non-taxable income flow into residual without tax deductions (no gross-up needed for residual; 125% gross-up is for DTI). A $2,800 BAH alone can move a file from short to 120%+.","M26-7 Ch.4.9"],
["Seller concessions (4%) can pay off debts","Paying off a $450/mo car note with seller concessions cuts both DTI and the residual deduction; VA treats debt payoff as a concession within the 4% cap, and the veteran's closing costs are unlimited on top.","M26-7 Ch.8.5"],
["Use the justification statement when residual is 100–119%","If DTI >41% and residual is above the table but under 120%, the underwriter can still approve with a written justification citing compensating factors (long employment, minimal payment shock, reserves, conservative credit). Draft it for them with the UW Advocacy memo builder.","M26-7 Ch.4.10"],
["Family size is the veteran's dependents, not the loan's borrowers","A single veteran with no dependents is family size 1; a non-purchasing spouse and children count. Verify on the 1003 and the LES (dependents code) — an overstated family size inflates the required residual.","M26-7 Ch.4.9"],
["Shop overlays, not rates, on tough VA files","No minimum score, no DTI cap, no reserves on 1-unit, no flip rule and no prepayment penalty are VA rules; everything stricter is a lender overlay. Keep a list of lenders that underwrite to the Handbook for scores under 620 and DTI over 55%.","M26-7 Ch.4; lender matrices"],
["Call the Regional Loan Center before you give up",`A loan technician at ${VA_RLC_PHONE} can confirm eligibility quirks, restoration, prior approval and appraisal issues the same day. Document the name and date in the file.`,"benefits.va.gov"],
];
/* Compensating factors — deep review (M26-7 Ch.4.10). Each: id, name, what VA means, the bar that makes it an "unusual strength", how to document, how to present, mistakes, strength weight */
const VA_COMP_FACTORS=[
{id:"credit",n:"Excellent credit history",va:"A sustained record of paying every obligation as agreed — not merely 'no lates in 12 months'.",bar:"24+ months with zero 30-day lates on all accounts, 5+ years of credit history, no derogatory items in 7 years, scores 740+ (score is a proxy; VA reads the history).",doc:"Tri-merge report; 24-month housing history (VOR/VOM or 12 months canceled checks); LOE for any blemish older than 24 months.",present:"'Borrower has paid 14 tradelines as agreed for 9 years with no late payment in 84 months; housing history 0×30 for 36 months.' Quote the numbers, not adjectives.",mistake:"Calling a 680 'excellent'. The factor is history, not a passing score; a 760 with a 60-day late last year is not excellent.",w:3,q:[["lates24","30-day lates in the last 24 months",0,"n"],["hist","Years of credit history",6,"n"],["fico","Score",740,"n"]],test:a=>+a.lates24===0&&+a.hist>=5&&+a.fico>=720},
{id:"conservative",n:"Conservative use of consumer credit",va:"The veteran uses credit sparingly and keeps balances low relative to limits.",bar:"Aggregate revolving utilization under 20%, no cash advances, no new accounts in 12 months, cards paid in full or near-full monthly.",doc:"Credit report utilization; 2–3 months of card statements showing payment in full; no inquiries in 12 months.",present:"'Revolving utilization 8% across $42,000 of available credit; no new credit in 18 months.'",mistake:"Ignoring utilization because the score is fine — underwriters check the ratio.",w:2,q:[["util","Revolving utilization %",15,"n"],["newacct","New accounts in last 12 months",0,"n"]],test:a=>+a.util<=20&&+a.newacct===0},
{id:"minimaldebt",n:"Minimal consumer debt",va:"Few installment/revolving obligations so the housing payment is the only material debt.",bar:"Total non-housing monthly debt under 8–10% of gross income; no auto loans or they pay off within 10 months; no revolving minimums over $100.",doc:"Debt schedule on the 1003 with balances/payments; payoff letters for accounts closing before funding.",present:"'Non-housing debt is $185/month (2.1% of income); DTI is driven entirely by the housing payment.'",mistake:"Paying off debts with closing funds the veteran needs — use seller concessions (4%) for debt payoff instead.",w:2,q:[["debtpct","Non-housing debt % of gross income",5,"n"]],test:a=>+a.debtpct<=10},
{id:"employment",n:"Long-term employment",va:"Stable, continuous employment with the same employer or in the same line of work.",bar:"5+ years same employer or 7+ years in the same field; military service counts as employment and a civilian job in the same MOS field continues the stability.",doc:"VOE with hire date; LES with pay entry base date (PEBD) for active duty; DD-214 + offer letter for transitioning members showing the same field.",present:"'11 years with the same employer; promoted twice; income increased 22% over 3 years.'",mistake:"Treating a PCS or ETS as a job change — show USERRA rights, orders, or the continuing career field.",w:2,q:[["yrs","Years with employer / in field",6,"n"]],test:a=>+a.yrs>=5},
{id:"assets",n:"Significant liquid assets",va:"Cash or near-cash the veteran will still have after closing (VA requires no reserves on 1-unit, so any reserves are a strength).",bar:"6+ months of PITIA in liquid accounts after closing (12+ is exceptional); retirement accounts count at the vested balance less penalties by lender policy.",doc:"2 months statements (all pages), 401(k)/TSP statement with vesting and terms of withdrawal; source of large deposits.",present:"'Post-closing reserves of $38,400 = 9.3 months PITIA, held 14+ months.'",mistake:"Counting gift funds or the earnest money as reserves; forgetting TSP for service members.",w:3,q:[["resmo","Months PITIA in reserves after closing",6,"n"]],test:a=>+a.resmo>=6},
{id:"down",n:"Sizable down payment",va:"Any down payment on a $0-down program is an unusual strength; it also cuts the funding fee at 5% and 10%.",bar:"5%+ from the veteran's own funds (10%+ exceptional).",doc:"Asset statements sourcing the funds; gift letters if gifted (still counts, lender-dependent).",present:"'Veteran is investing $27,500 (5%) of own funds, reducing the funding fee from 2.15% to 1.50%.'",mistake:"Forgetting to re-run the funding fee at the lower tier.",w:2,q:[["downpct","Down payment % of price",0,"n"]],test:a=>+a.downpct>=5},
{id:"equity",n:"Existence of equity in refinancing loans",va:"On a refinance, meaningful equity remaining after the new loan (low LTV) reduces VA's and the lender's loss exposure.",bar:"New LTV ≤ 80% (≤ 90% still notable on cash-out where 100% is allowed).",doc:"NOV/appraisal; payoff statement; title.",present:"'Post-refinance LTV 71%; veteran retains $212,000 of equity.'",mistake:"Maxing a cash-out to 100% when the residual is marginal — leave equity and cite it.",w:2,q:[["ltv","New LTV % (refi)",80,"n"]],test:a=>+a.ltv<=80},
{id:"shock",n:"Little or no increase in shelter expense",va:"The new PITIA is close to the current rent or mortgage payment, so the veteran is already living at this budget.",bar:"Payment increase ≤ 10% (or ≤ $100); a decrease is exceptional.",doc:"12 months rent evidence (VOR from a management company or canceled checks) or current mortgage statement; proposed PITIA.",present:"'Current rent $2,650; proposed PITIA $2,740 — 3.4% increase, no payment shock.'",mistake:"Comparing to BAH instead of what the veteran actually pays; underwriters compare to the actual housing expense.",w:3,q:[["cur","Current housing payment $",2600,"n"],["newp","Proposed PITIA $",2700,"n"]],test:a=>+a.cur>0&&(+a.newp-+a.cur)/+a.cur<=0.10},
{id:"ownership",n:"Satisfactory homeownership experience",va:"The veteran has owned and paid a mortgage on time before.",bar:"24+ months of mortgage history 0×30 (prior or current); multiple prior mortgages paid as agreed.",doc:"VOM or credit report mortgage tradeline; HUD-1/CD from prior sale.",present:"'Veteran paid a $1,900 mortgage 0×30 for 6 years before PCS; sold with equity.'",mistake:"Overlooking a prior VA loan that was paid as agreed — it also proves the veteran manages the benefit.",w:2,q:[["mtgmo","Months of on-time mortgage history",24,"n"]],test:a=>+a.mtgmo>=24},
{id:"residual",n:"Residual income exceeds the table by 20%+",va:"The decisive VA factor: residual at ≥120% of the regional table overrides the 41% DTI benchmark; at very high ratios the underwriter still has discretion.",bar:"≥120% of table (≥150% exceptional). Compute on actual tax withholding, family size, 14¢/sq ft maintenance, childcare and all debts.",doc:"Residual income worksheet; LES/pay stubs with withholding; award letters for non-taxable income; childcare statement.",present:"'Residual $1,872 vs $1,117 required (168%) for a family of 4 in the West region; DTI 49% is therefore within guideline under Ch.4.10.'",mistake:"Not checking residual until the AUS returns REFER; using estimated instead of actual taxes; wrong family size.",w:4,q:[["respct","Residual % of table",120,"n"]],test:a=>+a.respct>=120},
{id:"childtax",n:"Tax credits for child care",va:"The Child and Dependent Care Credit (and the Child Tax Credit) raise after-tax cash flow beyond what the LES withholding shows.",bar:"Documented credits that offset the childcare expense deducted in residual (e.g., $1,200–$2,100 dependent-care credit; $2,000/child CTC).",doc:"Prior-year 1040 with Form 2441 and Schedule 8812; childcare provider statement.",present:"'Childcare of $900/mo is partially offset by a $2,100 dependent-care credit and $4,000 CTC ($508/mo), which the withholding-based residual does not reflect.'",mistake:"Double-counting: either reduce the tax line or cite the credit as a factor, not both.",w:1,q:[["ctc","Annual child-related tax credits $",0,"n"]],test:a=>+a.ctc>=2000},
{id:"taxbenefit",n:"Tax benefits of home ownership",va:"Mortgage interest, property tax and (from 2026) MIP/funding-fee deductions lower the veteran's effective tax, improving real residual.",bar:"Itemizing produces a material benefit (interest + taxes above the standard deduction), typically on loans above ~$450k in California.",doc:"Estimate using the first-year interest (amortization schedule) and property tax; a CPA letter or the Tax Benefit calculator printout.",present:"'First-year interest $31,600 + property tax $6,900 exceed the standard deduction by $9,400, worth ≈ $180/mo at the 22% bracket.'",mistake:"Overstating: the benefit is only the amount above the standard deduction, and some lenders ignore it.",w:1,q:[["taxben","Estimated monthly tax benefit $",0,"n"]],test:a=>+a.taxben>=100},
{id:"military",n:"Military-specific strengths (VA practice)",va:"Not on the slide, but underwriters weigh: BAH/BAS continuing, tax-free disability income, retirement pay with COLA, re-enlistment/years to retirement, and prior VA loan performance.",bar:"Non-taxable income ≥25% of total; 4+ years to ETS or retirement vested; disability rating with permanent status.",doc:"LES, orders, re-enlistment contract, VA award letter, retirement orders.",present:"'$3,100 BAH and $1,450 disability are non-taxable (38% of income) and continue for 6+ years; funding fee exempt.'",mistake:"Grossing up for DTI but forgetting residual already counts it at 100%.",w:2,q:[["nontaxpct","Non-taxable income % of total",0,"n"]],test:a=>+a.nontaxpct>=25},
];
